\label{thm:main-centered}
For every $\varepsilon>0$ there is $N_0$ such that, for all
$0<\mu<L$, $N\ge N_0$ and $\mathcal R\in\mathfrak E_N(\mu,L)$,
\begin{equation}\label{eq:main-A-lower}
 A_N(\mathcal R)\ge(2\sqrt{c_{\mathrm{cert}}}-\varepsilon)
 \frac{N^{3/2}\epsilon_N^\star}{L-\mu},
 \qquad
 A_N(\mathcal R_N^\star)\le(2\sqrt{c_{\sin}}+\varepsilon)
 \frac{N^{3/2}\epsilon_N^\star}{L-\mu},
\end{equation}
where $\mathcal R_N^\star$ is the sine--Jacobi recurrence. Consequently
\begin{equation}\label{eq:main-centered-ratio}
 \limsup_{N\to\infty}\ \sup_{0<\mu<L}
 \frac{A_N(\mathcal R_N^\star)}
 {\inf_{\mathcal R\in\mathfrak E_N(\mu,L)}A_N(\mathcal R)}
 \le\sqrt{\frac{c_{\sin}}{c_{\mathrm{cert}}}}<1.000004 .
\end{equation}

\label{thm:gain}
For $J\in\overline{\mathcal Y}_N$, with $\widehat P_j(z)=\det(zI-J_{[j+2:N]})$ for $0\le j<N$,
\begin{equation}\label{eq:full-gain}
 A_N(\mathcal R_J)
 =\frac2{\Delta P_N(z_0)}
 \max_{x,y\in[-1,1]}
       \Bigl(\sum_{j=0}^{N-1}\widehat P_j(x)^2P_j(y)^2\Bigr)^{1/2}
 \ \ge\ \frac{2\epsilon_N^\star}{\Delta}\sqrt{\mathcal E_N(J)},
\end{equation}
and the maximum is attained in dimension $p=2$. Consequently
$\mathscr G(\mu,L)\ge2\sqrt{\underline{\mathsf e}}$.

\label{thm:packing}
For every $J\in\overline{\mathcal Y}_N$ there are bounded closed intervals $I_i$ with
disjoint interiors and lengths $|I_i|=1/d_i$ such that the density
\[
 m_J=\sum_{i=1}^N\frac{d_i^2}{N^2}\mathbf1_{I_i}
\]
belongs to $\mathcal M_c$, satisfies $E(m_J)=N^{-3}\mathcal E_N(J)$, and
\begin{equation}\label{eq:block-spectral-error}
 \sum_{j\ge0}\bigl|\lambda_j(K_{m_J})-\lambda_j(G/N^2)\bigr|
 \le\frac2{\sqrt N}+\frac1N .
\end{equation}

\label{lem:base-identity}
For a calibration, $\Gamma_\varsigma$ is continuous,
$0\le\Gamma_\varsigma(q)\le\min\{q^2,(2-q)^2\}$, the root $\nu_\kappa(q)$ is unique
and jointly continuous in $(\kappa,q)\in(0,\infty)\times[0,2]$, and
$d_\kappa>2Q$ on $(0,2)$. Along every density, almost everywhere,
\begin{equation}\label{eq:calibration-pointwise}
 f_\varsigma^2+\bigl(\mathcal J_\varsigma(h_\varsigma)\bigr)'=F_\varsigma(q,h_\varsigma).
\end{equation}
Every $m\ge0$ with $\int m=1$, $E(m)<\infty$ and $\kappa(m)=\kappa$
satisfies
\begin{equation}\label{eq:base-deficit}
 E(m)=\mathcal B_\kappa(m)+\int_\mathbb R\Bigl[\rho\bigl(n,\nu_\kappa(q)\bigr)
 +\omega\,\mathcal T\Bigr]\,\mathrm d x,\qquad
 \mathcal T=F_\varsigma(q,h_\varsigma)-\Gamma_\varsigma(q)\ge0,
\end{equation}
where both integrands are nonnegative and integrable.

\label{prop:baseline}
For any calibration of \Cref{def:base}, put
\begin{equation}\label{eq:baseline-value}
 \mathcal B_*=-b+\frac{2b}k+\frac3{2k}\int_0^2\nu_k\,\mathrm d q
 -\omega\mathcal J_\varsigma(2)
 -\omega\Bigl(\frac k\varsigma-\frac{2H_*(\varsigma k)}{\varsigma^2}\Bigr).
\end{equation}
Every integrable $m\ge0$ with $\int m=1$, $\kappa(m)=k$ and
$H_m(\varsigma k)=H_*(\varsigma k)$ satisfies $E(m)\ge\mathcal B_*$.
Moreover, $\underline{\mathsf e}\ge\mathcal B_*$.

\label{thm:common-measure}
Let $m$ be as in \Cref{lem:filter}. At every $x$ with $q(x)>0$ there is
a probability measure $\mu_x$ on $[0,1]$ such that
\begin{equation}\label{eq:common}
 \frac{\kappa r_s(x)}{sq(x)}
   =\int_0^1\frac{1-z}{1+(s/\kappa)z}\,\mathrm d\mu_x(z)\quad(s>0),\qquad
 \frac{r_\circ(x)}{q(x)}=\int_0^1(1-z)\,\mathrm d\mu_x(z).
\end{equation}
If $q(x)=0$, then $r_s(x)=r_\circ(x)=0$ for all $s$.

\label{def:dual}
A dual certificate $\Theta$ consists of
\begin{enumerate}
\item a calibration (\Cref{def:base}) with rational $\varsigma,b>0$,
$\omega\ge0$, and $g=g_\circ$ the contact potential
(\Cref{thm:contact}) of a reference profile
\[
 b_\circ(Q)=p_0+\sum_jp_j\frac{Q}{Q+\zeta_j}
 \qquad(\text{finitely many rational }p_0,p_j,\zeta_j>0);
\]
\item a potential
\begin{equation}\label{eq:transport-potential}
 \Psi_{\rm raw}=(2-q)^2\bigl[P_h(q)h+qP_0(q)u_0+qP_1(q)u_1
 +P_{00}(q)u_0^2+P_{01}(q)u_0u_1+P_{11}(q)u_1^2\bigr]
\end{equation}
with polynomials $P_\bullet$ with rational coefficients;
\item rational multipliers $\xi_0,\xi_1,\chi,\tau$;
\item for each side $\mathrm s\in\{\mathrm L,\mathrm R\}$, a partition of
$[0,1]$ into closed intervals $\mathsf C$ ({cells}) and a rational
affine function $e_{\mathsf C}$ on each cell (the {price}).
\end{enumerate}

\label{def:admissible}

A dual certificate is {admissible at $\kappa$} if, for every side,
cell $\mathsf C$ and end $\sigma$,
\begin{equation}\label{eq:witness}
 \max_{(t,U,T)\in\mathsf C\times[0,1]^2}
 \Bigl[\psi\bigl(\mathfrak b_\sigma-e_{\mathsf C}\bigr)-\mathfrak c_\sigma
 -e_{\mathsf C}(1-\mathfrak l)\Bigr]<0 .
\end{equation}
Its {value} at a density $m$ with $\kappa(m)=\kappa$ is
\begin{equation}\label{eq:dual-value}
 \ell_\kappa(\Theta;m)=\mathcal B_\kappa(m)
 +\sum_{i=0}^1\xi_i\bigl[H_m(s_i)-H_{\bar m_\kappa}(s_i)\bigr]
 +\chi\bigl[S(m)-S(\bar m_\kappa)\bigr]-\mathcal P_\kappa,
\end{equation}
with
\begin{equation}\label{eq:closed-price-main}
 \mathcal P_\kappa=\sum_{\mathrm s,\mathsf C}\int_{\mathsf C}
 \frac{3t^3\hat\nu_\kappa(t)}{\kappa}e_{\mathsf C}(t)\,\mathrm d t
 +\tau\Bigl(1-\int\bar m_\kappa\Bigr).
\end{equation}
Its {target value} is the value at $\kappa=k$ with the target
observations:
\begin{equation}\label{eq:dual-target-value}
 \ell_*(\Theta)=\mathcal B_*
 +\sum_{i=0}^1\xi_i\,\delta H_i+\chi\,\delta S
 -\Pi-\tau\Bigl(1-\int\bar m_k\Bigr),
\end{equation}
where $\mathcal B_*$ is defined in \eqref{eq:baseline-value} and
\[
 \Pi=\sum_{\mathrm s,\mathsf C}\int_{\mathsf C}
 \frac{3t^3\hat\nu_k(t)}{k}e_{\mathsf C}(t)\,\mathrm d t,
\]
\[
 \delta H_i=H_*(s_i)-H_{\bar m_k}(s_i),\qquad
 \delta S=\frac{k^2}6-S(\bar m_k).
\]

\label{thm:dual}
Let $\Theta$ be admissible at $k$. Then
\begin{enumerate}
\item every $m\in\mathcal A_{\mathrm{obs}}(\varsigma)$ satisfies $E(m)\ge\ell_*(\Theta)$;
\item for every $\varepsilon>0$ there is $N_0$ such that
$N^{-3}\mathcal E_N(J)\ge\ell_*(\Theta)-\varepsilon$ for all $N\ge N_0$ and
$J\in\overline{\mathcal Y}_N$. Hence $\underline{\mathsf e}\ge\ell_*(\Theta)$ and, if
$\ell_*(\Theta)\ge0$, $\mathscr G(\mu,L)\ge2\sqrt{\ell_*(\Theta)}$ for all
$0<\mu<L$.
\end{enumerate}

\label{ca:transport}
\begin{enumerate}
\item $\Theta_{\mathrm{cert}}$ is admissible at $k$.
\item The quantities in \Cref{tab:reference-enclosures} lie in the stated
intervals.
\end{enumerate}

\label{cor:primal}
The primal certificate satisfies the hypotheses of \Cref{thm:primal} with
$\varepsilon_F=6.7299\cdot10^{-17}$ and $\theta_F=1.818\cdot10^{-7}$, and
\[
 \begin{gathered}
 c_{\mathrm{cert}}\le\inf_{\mathcal A_{\mathrm{obs}}(\varsigma_{\mathrm{cal}})\cap\mathcal M_c}E
 \le E(m_{\mathrm{feas}})\le U_{\mathrm{feas}}<c_{\sin},\\
 U_{\mathrm{feas}}:=\ensuremath{\csname computed/feasible/energy_ceiling/hi24\endcsname}.
 \end{gathered}
\]

\label{hyp:sine-lower}
$\underline{\mathsf e}=c_{\sin}$. Consequently $\mathscr G(\mu,L)=2\sqrt{c_{\sin}}$ for all
$0<\mu<L$.

\label{lem:gain-kernel}
For $J\in\overline{\mathcal Y}_N$, every $p\ge1$, every symmetric $p\times p$ matrix $H$
with $\mu I\preceq H\preceq LI$, and real $p\times p$ matrices $B=(B_0,\dots,B_{N-1})$,
with $Z=z_0I-2H/\Delta$,
\begin{equation}\label{eq:gain-kernel}
 \mathsf D_{\mathcal R_J,H}[B]
 =-\frac2{\Delta P_N(z_0)}\sum_{j=0}^{N-1}\widehat P_j(Z)B_jP_j(Z).
\end{equation}

\label{proof:thm:comparisons}
By \Cref{lem:local-profile}, $\nu_\kappa$ is a comparison profile at $\kappa$
with density $\bar m_\kappa$, and \Cref{lem:comparison-general} applies.

\label{proof:lem:mobius}
$2(1+UR)-D=2UR-q\alpha U-\delta_qR$, and $q\alpha U=2\alpha U-\delta_q\alpha U$; this
gives the first identity. The second follows from $q=2-\delta_q$.
